import math

def verifier(assign):
    # Basic presence and type checks
    if not all(k in assign for k in ['p', 'q', 'a1', 'a2']):
        # Missing required keys
        return False, None  # missing keys
    p = assign['p']
    q = assign['q']
    a1s = assign['a1']
    a2s = assign['a2']
    if not isinstance(p, int) or not isinstance(q, int):
        return False, None  # p and q must be integers
    if p < 3 or q < 2 or p == q:
        return False, None  # hardness/domain constraints violated

    # Parse a1, a2 as exact Fractions
    def parse_frac(s):
        if isinstance(s, (int, float)):
            # Convert numeric to Fraction (discouraged, but handle)
            return Fraction(s).limit_denominator()
        if not isinstance(s, str):
            return None
        s = s.strip()
        if '/' in s:
            num, den = s.split('/')
            try:
                return Fraction(int(num), int(den))
            except Exception:
                return None
        else:
            try:
                return Fraction(int(s), 1)
            except Exception:
                return None
    a1 = parse_frac(a1s)
    a2 = parse_frac(a2s)
    if a1 is None or a2 is None:
        return False, None  # invalid fraction formatting

    # Recover u from a2: a2 = (u^2 + 1)/(2u) => u = a2 + sqrt(a2^2 - 1)
    s = a2*a2 - Fraction(1, 1)
    # Check s is a perfect square rational
    N = s.numerator
    D = s.denominator
    rN = math.isqrt(N)
    rD = math.isqrt(D)
    if rN*rN != N or rD*rD != D:
        return False, None  # not a perfect square, invalid instance
    sqrt_s = Fraction(rN, rD)
    u_frac = a2 + sqrt_s
    if u_frac.denominator != 1:
        return False, None  # u must be integer
    u = u_frac.numerator
    if u < 2:
        return False, None  # domain constraint

    # Validate that a1 matches construction (A=u^p)
    A = u**p
    a1_expected = Fraction(A*A + 1, 2*A)
    if a1 != a1_expected:
        return False, None  # a1 not consistent

    # Build the closed-form answer. Let counts of odd/even steps among 1..n-1 be c_odd, c_even
    # Then t_n = (p*ln u) / (p^{c_odd} q^{c_even}) = ln u * p^{1 - c_odd} / q^{c_even}
    # c_odd = ceil((n-1)/2), c_even = floor((n-1)/2)
    answer = (
        "a_n = \\cosh\\!\\left(\\frac{\\ln "
        + str(u)
        + " \\cdot "
        + str(p)
        + "^{1-\\lceil (n-1)/2 \\rceil}}{"
        + str(q)
        + "^{\\lfloor (n-1)/2 \\rfloor}}\\right)"
    )

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

